CREATE TABLE scratch_actors (id TEXT PRIMARY KEY, user_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE scratch_issues (id TEXT PRIMARY KEY, game_id TEXT NOT NULL, revision TEXT NOT NULL, config TEXT NOT NULL, prize_pool TEXT NOT NULL, seed TEXT NOT NULL, seed_commit TEXT NOT NULL, pool_hash TEXT NOT NULL, seed_reveal TEXT, status TEXT NOT NULL DEFAULT 'IN_STOCK', box_size INTEGER NOT NULL DEFAULT 100, pack_size INTEGER NOT NULL DEFAULT 10, created_at TEXT NOT NULL, UNIQUE(game_id,revision));
CREATE TABLE scratch_books (id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES scratch_issues(id), book_number INTEGER NOT NULL, total INTEGER NOT NULL, cursor INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'SEALED', UNIQUE(issue_id,book_number), CHECK(cursor>=0 AND cursor<=total));
CREATE TABLE scratch_orders (id TEXT PRIMARY KEY, owner TEXT NOT NULL, issue_id TEXT NOT NULL, book_number INTEGER NOT NULL, quantity INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE scratch_reservations (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES scratch_orders(id), owner TEXT NOT NULL, book_id TEXT NOT NULL, first_index INTEGER NOT NULL, quantity INTEGER NOT NULL, applied INTEGER NOT NULL DEFAULT 0);
CREATE TABLE scratch_tickets (id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES scratch_issues(id), game_id TEXT NOT NULL, book_number INTEGER NOT NULL, ticket_number INTEGER NOT NULL, ticket_index INTEGER NOT NULL, serial TEXT NOT NULL UNIQUE, denomination INTEGER NOT NULL, prize_tier TEXT NOT NULL, prize INTEGER NOT NULL, play_data TEXT NOT NULL, data_hash TEXT NOT NULL, logistics_code TEXT NOT NULL UNIQUE, validation_code TEXT NOT NULL UNIQUE, owner TEXT NOT NULL, order_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'SOLD' CHECK(status IN ('SOLD','PARTIAL','SCRATCHED','REDEEMED','VOID','EXPIRED')), masks TEXT NOT NULL DEFAULT '[]', revealed TEXT NOT NULL DEFAULT '[]', security_opened INTEGER NOT NULL DEFAULT 0, security_opened_at TEXT, created_at TEXT NOT NULL, sold_at TEXT NOT NULL, scratched_at TEXT, redeemed_at TEXT, UNIQUE(issue_id,ticket_index));
CREATE INDEX scratch_owner_game ON scratch_tickets(owner,game_id,ticket_index);
CREATE INDEX scratch_issue_prize ON scratch_tickets(issue_id,prize,status);
CREATE TABLE scratch_ledger (ticket_id TEXT PRIMARY KEY REFERENCES scratch_tickets(id), units INTEGER NOT NULL CHECK(units>=0), created_at TEXT NOT NULL);
CREATE TABLE scratch_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TRIGGER scratch_immutable_issue BEFORE UPDATE OF game_id,revision,config,prize_pool,seed,seed_commit,pool_hash,box_size,pack_size,created_at ON scratch_issues BEGIN SELECT RAISE(ABORT,'Immutable production batch'); END;
CREATE TRIGGER scratch_immutable_ticket BEFORE UPDATE OF issue_id,game_id,book_number,ticket_number,ticket_index,serial,denomination,prize_tier,prize,play_data,data_hash,logistics_code,validation_code,created_at,sold_at ON scratch_tickets BEGIN SELECT RAISE(ABORT,'Immutable ticket print'); END;
CREATE TRIGGER scratch_lifecycle BEFORE UPDATE OF status ON scratch_tickets WHEN NOT (OLD.status=NEW.status OR (OLD.status='SOLD' AND NEW.status IN ('PARTIAL','VOID','EXPIRED')) OR (OLD.status='PARTIAL' AND NEW.status IN ('SCRATCHED','VOID','EXPIRED')) OR (OLD.status='SCRATCHED' AND NEW.status IN ('REDEEMED','VOID','EXPIRED'))) BEGIN SELECT RAISE(ABORT,'Invalid ticket lifecycle'); END;
